try:
    print('>>> x = range(0)')
    print('>>> y = 1j')
    print('>>> x *= y')
    print('>>> x')
    x = range(0)
    y = 1j
    x *= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
